            assigneeId: issue.assigneeId,
          });
          stillReported.add(issue.id);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to announce overdue issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }

      swept.set(orgId, stillReported);
    }

    // Deleted organizations are no longer swept, so their entries go too.
    reported.clear();
    for (const [orgId, ids] of swept) reported.set(orgId, ids);
  });
}

