import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];
const PAST = "2026-01-01T00:00:00.000Z";
const FUTURE = "2027-12-31T00:00:00.000Z";
const NOW = new Date("2026-06-01T07:00:00.000Z");

async function insertIssue(tenant: Tenant, dueAt: string | null, assigneeId = tenant.userIds.member) {
  const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
  return issueRepo.insertIssue(
    issueInput(tenant.org.id, tenant.project.id, { dueAt, assigneeId }),
    tenant.userIds.owner,
    number,
  );
}

function watch(): string[] {
  const seen: string[] = [];
  detachers.push(subscribe("issue.overdue", (p) => void seen.push(p.issueId)));
  return seen;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  resetOverdueTracking();
});
afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});
afterAll(() => cleanup());

describe("scratch", () => {
  it("covers new orgs, skips deleted ones, canceled, exact-now", async () => {
    const fresh = await createTenant("fresh");
    const gone = await createTenant("gone");
    const late = await insertIssue(fresh, PAST);
    const canceled = await insertIssue(fresh, PAST);
    await issueRepo.setIssueStatus(fresh.org.id, canceled.id, "canceled");
    const exact = await insertIssue(fresh, NOW.toISOString());
    const goneIssue = await insertIssue(gone, PAST);
    await orgRepo.archiveOrg(gone.org.id);
    const seen = watch();
    await runOverdueIssueJob(NOW);
    expect(seen).toEqual([late.id]);
    expect(seen).not.toContain(exact.id);
    expect(seen).not.toContain(goneIssue.id);
    expect(seen).not.toContain(canceled.id);
  });

  it("re-announces after cancel/reopen and after due moved out", async () => {
    resetOverdueTracking();
    const t = await createTenant("again");
    const a = await insertIssue(t, PAST);
    const b = await insertIssue(t, PAST);
    const seen = watch();
    await runOverdueIssueJob(NOW);
    await runOverdueIssueJob(NOW);
    expect(seen.filter((x) => x === a.id)).toHaveLength(1);
    await issueRepo.setIssueStatus(t.org.id, a.id, "canceled");
    await issueRepo.updateIssue({ orgId: t.org.id, issueId: b.id, dueAt: FUTURE as never } as never);
    await runOverdueIssueJob(NOW);
    await issueRepo.setIssueStatus(t.org.id, a.id, "todo");
    await issueRepo.updateIssue({ orgId: t.org.id, issueId: b.id, dueAt: PAST as never } as never);
    await runOverdueIssueJob(NOW);
    await runOverdueIssueJob(NOW);
    expect(seen.filter((x) => x === a.id)).toHaveLength(2);
    expect(seen.filter((x) => x === b.id)).toHaveLength(2);
  });

  it("files overdue alerts as issue_overdue and honours only that preference", async () => {
    resetOverdueTracking();
    const t = await createTenant("prefs");
    await preferenceRepo.upsertPreference({
      orgId: t.org.id, userId: t.userIds.member, kind: "issue_due_soon", inApp: false, email: false, digestOnly: false,
    } as never);
    await insertIssue(t, PAST);
    await runOverdueIssueJob(NOW);
    const page = await notificationRepo.listNotifications({ orgId: t.org.id, recipientId: t.userIds.member, limit: 50 } as never);
    expect(page.items.map((n) => n.kind)).toEqual(["issue_overdue"]);

    const t2 = await createTenant("prefs2");
    await preferenceRepo.upsertPreference({
      orgId: t2.org.id, userId: t2.userIds.member, kind: "issue_overdue", inApp: false, email: false, digestOnly: false,
    } as never);
    await insertIssue(t2, PAST);
    await runOverdueIssueJob(NOW);
    const page2 = await notificationRepo.listNotifications({ orgId: t2.org.id, recipientId: t2.userIds.member, limit: 50 } as never);
    expect(page2.items).toHaveLength(0);
  });

  it("completion date and project stats", async () => {
    const t = await createTenant("stats");
    const i = await insertIssue(t, PAST);
    const started = await issueRepo.setIssueStatus(t.org.id, i.id, "in_progress");
    const done = await issueRepo.setIssueStatus(t.org.id, i.id, "done");
    expect(done.completedAt).not.toBeNull();
    const reopened = await issueRepo.setIssueStatus(t.org.id, i.id, "in_progress");
    expect(reopened.completedAt).toBeNull();
    expect(reopened.startedAt).toBe(started.startedAt);
    const canceled = await insertIssue(t, PAST);
    await issueRepo.setIssueStatus(t.org.id, canceled.id, "canceled");
    await insertIssue(t, FUTURE);
    const stats = await projectRepo.getProjectStats(t.org.id, t.project.id);
    expect(stats).toMatchObject({ openIssues: 2, closedIssues: 1, overdueIssues: 1 });
  });
});

